// Compile-time proof: every error of updateContact that the server can send is
// handled by catchTags, including the framework's InternalError and
// BodyTooLarge. The declared error channel of updateContactOutcome is only the
// transport and decoding errors (TransportError, generated by `effectgo ts`). If
// the Go handler gains an error with a status, the generated error list gains
// it, and `tsc --noEmit` fails at the annotated `handled` variable until this
// file handles it.

import { Effect } from "effect"
import type { HttpApiClient } from "effect/http-api"
import { Api, type Contact as ContactSchema, type ContactInput, type TransportError } from "./api.gen.ts"

type Contact = typeof ContactSchema.Type

export type UpdateOutcome =
  | { readonly outcome: "saved"; readonly contact: Contact }
  | { readonly outcome: "not-found" }
  | { readonly outcome: "invalid"; readonly detail: string }
  | { readonly outcome: "too-large" }
  | { readonly outcome: "server-error" }

export function updateContactOutcome(
  client: HttpApiClient.ForApi<typeof Api>,
  payload: typeof ContactInput.Type,
): Effect.Effect<UpdateOutcome, TransportError> {
  const handled: Effect.Effect<UpdateOutcome, TransportError> = client.store
    .updateContact({ payload })
    .pipe(
      Effect.map((contact): UpdateOutcome => ({ outcome: "saved", contact })),
      Effect.catchTags({
        ContactNotFound: () => Effect.succeed<UpdateOutcome>({ outcome: "not-found" }),
        ValidationError: (e) => Effect.succeed<UpdateOutcome>({ outcome: "invalid", detail: e.detail }),
        BodyTooLarge: () => Effect.succeed<UpdateOutcome>({ outcome: "too-large" }),
        InternalError: () => Effect.succeed<UpdateOutcome>({ outcome: "server-error" }),
        DecodeError: (e) =>
          Effect.succeed<UpdateOutcome>({
            outcome: "invalid",
            // issues and path are nullable in the generated schema (a Go nil slice is null).
            detail: (e.issues ?? []).map((i) => `${(i.path ?? []).join(".")}: ${i.message}`).join("; "),
          }),
      }),
    )
  return handled
}
